#!/usr/bin/env python3
"""Rebuild site/audio/manifest.js from the files in site/audio/clips/.

Run it after adding or removing clips (the deploy workflow also runs it):
    python3 tools/audio_manifest.py
"""
import json
from audio_common import AUDIO, existing_clips


def write_manifest() -> int:
    clips = existing_clips()
    body = json.dumps(clips, ensure_ascii=False, indent=0, sort_keys=True)
    AUDIO.mkdir(parents=True, exist_ok=True)
    (AUDIO / "manifest.js").write_text(
        "// Generated by tools/audio_manifest.py — do not edit by hand.\n"
        f"window.AUDIO_FILES = {body};\n",
        encoding="utf-8",
    )
    return len(clips)


if __name__ == "__main__":
    print(f"manifest lists {write_manifest()} clips")
